<?php
session_start(); require_once '../conexion.php';
if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='operario'){header('Location: ../login.php');exit;}
$usuario=isset($_SESSION['usuario'])?$_SESSION['usuario']:'';$id=(int)$_SESSION['usuario_id'];
$asignados=0;$completados=0;$r=$conexion->query("SELECT COUNT(*) AS total FROM pedidos WHERE operario_id=$id AND estado IN ('Pendiente','En proceso')");if($r){$asignados=(int)$r->fetch_assoc()['total'];}$r=$conexion->query("SELECT COUNT(*) AS total FROM pedidos WHERE operario_id=$id AND estado='Completado'");if($r){$completados=(int)$r->fetch_assoc()['total'];}
$stmt=$conexion->prepare("SELECT id,estado,fecha,total_productos FROM pedidos WHERE operario_id=? AND estado IN ('Pendiente','En proceso') ORDER BY id DESC");$stmt->bind_param('i',$id);$stmt->execute();$pedidos=$stmt->get_result();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Panel del Operario | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><nav class="sistema-navbar"><div class="navbar-brand-sistema"><div class="navbar-logo"><i class="bi bi-box-seam"></i></div><div><strong>SOFTYLE</strong><small>Sistema de Picking</small></div></div><div class="navbar-user"><div class="user-info"><span>Hola,</span><strong><?php echo htmlspecialchars($usuario,ENT_QUOTES,'UTF-8');?></strong></div><a href="../logout.php" class="btn-logout"><i class="bi bi-box-arrow-right"></i></a></div></nav><main class="dashboard-container"><section class="dashboard-header"><div><span class="dashboard-label">PANEL DEL OPERARIO</span><h1>Preparación de pedidos</h1><p>Seleccioná un pedido para comenzar el picking.</p></div></section><section class="stats-grid"><div class="stat-card"><div class="stat-icon blue"><i class="bi bi-clipboard-check"></i></div><div><span>Pedidos asignados</span><strong><?php echo $asignados;?></strong></div></div><div class="stat-card"><div class="stat-icon green"><i class="bi bi-check-circle"></i></div><div><span>Completados</span><strong><?php echo $completados;?></strong></div></div></section><section class="pedidos-section"><div class="section-title"><div><h2>Pedidos pendientes</h2><p>Pedidos listos para ser preparados.</p></div></div><?php if($pedidos->num_rows===0){?><div class="alert alert-info">No tenés pedidos pendientes.</div><?php }?><?php while($pedido=$pedidos->fetch_assoc()){?><article class="pedido-card"><div class="pedido-top"><div><span class="pedido-label">PEDIDO</span><h3>#<?php echo (int)$pedido['id'];?></h3></div><span class="estado <?php echo $pedido['estado']==='En proceso'?'en-proceso':'pendiente';?>"><?php echo htmlspecialchars($pedido['estado'],ENT_QUOTES,'UTF-8');?></span></div><div class="pedido-info"><div><i class="bi bi-box"></i><span><strong><?php echo (int)$pedido['total_productos'];?></strong> productos</span></div><div><i class="bi bi-calendar"></i><span><?php echo htmlspecialchars($pedido['fecha'],ENT_QUOTES,'UTF-8');?></span></div></div><a href="picking.php?id=<?php echo (int)$pedido['id'];?>" class="btn-picking"><?php echo $pedido['estado']==='En proceso'?'Continuar picking':'Comenzar picking';?> <i class="bi bi-arrow-right"></i></a></article><?php }?></section></main><script src="../JS/sistema.js"></script></body></html>
